package za.ac.cput.domain; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity public class Notification{@Id private String notificationId;private String customerId,bookingId,message,notificationType;private LocalDateTime sentAt; protected Notification(){} private Notification(Builder b){notificationId=b.notificationId;customerId=b.customerId;bookingId=b.bookingId;message=b.message;sentAt=b.sentAt;notificationType=b.notificationType;} public String getNotificationId(){return notificationId;} public String getCustomerId(){return customerId;} public String getBookingId(){return bookingId;} public String getMessage(){return message;} public LocalDateTime getSentAt(){return sentAt;} public String getNotificationType(){return notificationType;} public static class Builder{private String notificationId,customerId,bookingId,message,notificationType;private LocalDateTime sentAt; public Builder setNotificationId(String v){notificationId=v;return this;} public Builder setCustomerId(String v){customerId=v;return this;} public Builder setBookingId(String v){bookingId=v;return this;} public Builder setMessage(String v){message=v;return this;} public Builder setSentAt(LocalDateTime v){sentAt=v;return this;} public Builder setNotificationType(String v){notificationType=v;return this;} public Builder copy(Notification n){notificationId=n.notificationId;customerId=n.customerId;bookingId=n.bookingId;message=n.message;sentAt=n.sentAt;notificationType=n.notificationType;return this;} public Notification build(){return new Notification(this);}}}